import { Group, Mesh, PlaneGeometry, MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, texture as texNode } from 'three/tsl';
import { gsap } from 'gsap';
import {} from '@/primitives';
import {} from '@/text';

export default function createNode(config, ctx) {
  const { Group: CGroup, Mesh: CMesh, PlaneGeometry: CPlaneGeometry, MeshBasicNodeMaterial: CMeshBasicNodeMaterial } = ctx.THREE;

  // Create container
  const container = new CGroup();

  // Determine plane size from atlas region (512x320)
  const aspect = 512 / 320;
  const planeWidth = aspect;
  const planeHeight = 1;

  const geometry = new CPlaneGeometry(planeWidth, planeHeight);
  const material = new CMeshBasicNodeMaterial();

  const mesh = new CMesh(geometry, material);
  container.add(mesh);

  // Load texture if provided
  let loadedTexture = null;
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      loadedTexture = tex;
      const uvNode = uv();
      material.mapNode = texNode(tex, uvNode);
      material.needsUpdate = true;
    });
  }

  // No primitives to apply
  // No text content to render

  // Event handlers placeholder
  container.userData.handlers = {};

  // Cleanup routine
  container.userData.cleanup = () => {
    // Dispose resources
    if (loadedTexture) loadedTexture.dispose();
    material.dispose();
    geometry.dispose();
    // Kill any GSAP timelines (none in this node)
    gsap.globalTimeline.clear();
  };

  return container;
}
